<template>
  <div class="space-y-4">
    <h1 class="text-xl font-bold text-navy">More</h1>

    <div class="bg-white rounded-xl border border-border divide-y divide-border">
      <div class="p-4">
        <div class="text-sm font-medium">{{ user?.full_name }}</div>
        <div class="text-xs text-muted">{{ user?.email }}</div>
        <div class="text-xs text-muted mt-1">{{ (user?.roles || []).join(', ') }}</div>
        <div v-if="isSuperAdmin" class="text-[10px] text-primary font-semibold mt-1">Super Admin</div>
      </div>

      <Can perm="dashboard.view">
        <NuxtLink to="/dashboard" class="block p-4 text-sm hover:bg-canvas">Dashboard</NuxtLink>
      </Can>
      <Can :any="['transactions.view','income.view','expense.view']">
        <NuxtLink to="/transactions" class="block p-4 text-sm hover:bg-canvas">Transactions</NuxtLink>
      </Can>
      <Can :any="['income.create','expense.create']">
        <NuxtLink to="/transactions/new" class="block p-4 text-sm hover:bg-canvas">Add transaction</NuxtLink>
      </Can>
      <Can :any="['reports.view','dashboard.view']">
        <NuxtLink to="/reports" class="block p-4 text-sm hover:bg-canvas">Reports</NuxtLink>
      </Can>
    </div>

    <div v-if="showAdmin" class="bg-white rounded-xl border border-border divide-y divide-border">
      <div class="px-4 py-2 text-xs font-semibold text-muted uppercase tracking-wide">Administration</div>
      <Can perm="branches.view">
        <NuxtLink to="/admin/branches" class="block p-4 text-sm hover:bg-canvas">Branches</NuxtLink>
      </Can>
      <Can perm="users.view">
        <NuxtLink to="/admin/users" class="block p-4 text-sm hover:bg-canvas">Users</NuxtLink>
      </Can>
      <Can perm="roles.view">
        <NuxtLink to="/admin/roles" class="block p-4 text-sm hover:bg-canvas">Roles</NuxtLink>
      </Can>
      <Can perm="roles.view">
        <NuxtLink to="/admin/permissions" class="block p-4 text-sm hover:bg-canvas">Permission codes</NuxtLink>
      </Can>
      <Can perm="audit-logs.view">
        <NuxtLink to="/admin/audit" class="block p-4 text-sm hover:bg-canvas">Audit log</NuxtLink>
      </Can>
    </div>

    <div class="bg-white rounded-xl border border-border p-4">
      <div class="text-xs font-semibold text-muted uppercase mb-2">Your permissions</div>
      <div class="flex flex-wrap gap-1 max-h-32 overflow-y-auto">
        <span
          v-for="code in permissions"
          :key="code"
          class="text-[10px] px-1.5 py-0.5 rounded bg-canvas border border-border font-mono"
        >{{ code }}</span>
        <span v-if="isSuperAdmin && !permissions.length" class="text-xs text-muted">All (super admin)</span>
        <span v-if="!isSuperAdmin && !permissions.length" class="text-xs text-muted">None loaded</span>
      </div>
    </div>

    <div class="bg-white rounded-xl border border-border">
      <button class="w-full text-left p-4 text-sm text-expense hover:bg-canvas" @click="onLogout">
        Sign out
      </button>
    </div>
  </div>
</template>

<script setup lang="ts">
const { user, logout } = useAuth()
const {
  isSuperAdmin,
  permissions,
  canViewBranches,
  canViewUsers,
  canViewRoles,
  canViewAudit,
} = usePermissions()

const showAdmin = computed(
  () => canViewBranches.value || canViewUsers.value || canViewRoles.value || canViewAudit.value,
)

async function onLogout() {
  await logout()
  navigateTo('/login')
}
</script>
